package com.google.common.hash;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import org.junit.Test;

/**
 * Tests for Hashing.consistentHash(long, int) method.
 * Validates the refactored implementation that eliminates heap allocation
 * by inlining the LinearCongruentialGenerator logic.
 */
public class HashingConsistentHashTest {

  @Test
  public void testConsistentHash_validBuckets() {
    // Test with various bucket counts to ensure results are in valid range
    for (int buckets = 1; buckets <= 100; buckets++) {
      for (long input = 0; input < 100; input++) {
        int result = Hashing.consistentHash(input, buckets);
        assertTrue("Result should be in range [0, " + (buckets - 1) + "], got: " + result, 
            result >= 0 && result < buckets);
      }
    }
  }

  @Test
  public void testConsistentHash_deterministic() {
    // Same input should always produce same output (deterministic behavior)
    long input = 42L;
    int buckets = 10;
    int expected = Hashing.consistentHash(input, buckets);

    for (int i = 0; i < 100; i++) {
      assertEquals("Result should be deterministic for same input", 
          expected, Hashing.consistentHash(input, buckets));
    }
  }

  @Test
  public void testConsistentHash_invalidBuckets_zero() {
    // Test that zero buckets throws IllegalArgumentException
    try {
      Hashing.consistentHash(42L, 0);
      fail("Should throw IllegalArgumentException for buckets = 0");
    } catch (IllegalArgumentException e) {
      assertTrue("Exception message should mention buckets", 
          e.getMessage().contains("buckets"));
    }
  }

  @Test
  public void testConsistentHash_invalidBuckets_negative() {
    // Test that negative buckets throws IllegalArgumentException
    try {
      Hashing.consistentHash(42L, -1);
      fail("Should throw IllegalArgumentException for negative buckets");
    } catch (IllegalArgumentException e) {
      assertTrue("Exception message should mention buckets", 
          e.getMessage().contains("buckets"));
    }
  }

  @Test
  public void testConsistentHash_largeInputs() {
    // Test with large input values including edge cases
    long[] largeInputs = {
      Long.MAX_VALUE,
      Long.MIN_VALUE,
      0xFFFFFFFFL,
      0x7FFFFFFFFFFFFFFFL,
      0x8000000000000000L
    };

    for (long input : largeInputs) {
      int result = Hashing.consistentHash(input, 100);
      assertTrue("Result should be in range [0, 99] for input: " + input, 
          result >= 0 && result < 100);
    }
  }

  @Test
  public void testConsistentHash_singleBucket() {
    // With 1 bucket, should always return 0
    for (long input = 0; input < 100; input++) {
      assertEquals("With 1 bucket, result should always be 0", 
          0, Hashing.consistentHash(input, 1));
    }
  }

  @Test
  public void testConsistentHash_twoBuckets() {
    // With 2 buckets, result should be 0 or 1
    for (long input = 0; input < 100; input++) {
      int result = Hashing.consistentHash(input, 2);
      assertTrue("Result should be 0 or 1", result == 0 || result == 1);
    }
  }

  @Test
  public void testConsistentHash_consistencyAcrossBucketChanges() {
    // Test that the algorithm produces consistent results as buckets change
    // This validates the consistent hashing property
    long input = 12345L;

    for (int buckets = 1; buckets <= 50; buckets++) {
      int result = Hashing.consistentHash(input, buckets);
      assertTrue("Result should be in range [0, " + (buckets - 1) + "]", 
          result >= 0 && result < buckets);
    }
  }

  @Test
  public void testConsistentHash_variousInputs() {
    // Test with a variety of input values to ensure broad coverage
    long[] testInputs = {0, 1, 2, 100, 1000, 10000, -1, -100, -1000};
    int[] testBuckets = {1, 5, 10, 50, 100, 1000};

    for (long input : testInputs) {
      for (int buckets : testBuckets) {
        int result = Hashing.consistentHash(input, buckets);
        assertTrue("Result should be in range [0, " + (buckets - 1) + 
            "] for input=" + input + ", buckets=" + buckets, 
            result >= 0 && result < buckets);
      }
    }
  }

  @Test
  public void testConsistentHash_noAllocation() {
    // This test verifies the method can be called many times without issues
    // The refactored version should not allocate LinearCongruentialGenerator objects
    long input = 42L;
    int buckets = 100;

    // Call the method many times to ensure no allocation-related issues
    for (int i = 0; i < 10000; i++) {
      int result = Hashing.consistentHash(input + i, buckets);
      assertTrue("Result should be in valid range", result >= 0 && result < buckets);
    }
  }
}

