package com.google.common.collect;

import static com.google.common.truth.Truth.assertThat;
import static org.junit.Assert.assertThrows;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Iterator;
import java.util.List;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;

/**
 * Tests for the new {@link Iterators#transform(Iterator, java.util.function.Function)} overload.
 * This test class verifies that the new JDK Function-based transform method works correctly,
 * including transformation logic, remove delegation, and null safety.
 */
@RunWith(JUnit4.class)
public class IteratorsTransformJdkFunctionTest {

  @Test
  public void testTransform_withJdkFunction() {
    List<String> input = Arrays.asList("1", "2", "3");
    Iterator<String> sourceIterator = input.iterator();

    // Explicitly use java.util.function.Function to target the new overload
    java.util.function.Function<String, Integer> function = Integer::valueOf;

    Iterator<Integer> result = Iterators.transform(sourceIterator, function);

    assertThat(Lists.newArrayList(result)).containsExactly(1, 2, 3).inOrder();
  }

  @Test
  public void testTransform_removeDelegation() {
    List<String> input = new ArrayList<>(Arrays.asList("1", "2", "3"));
    Iterator<String> sourceIterator = input.iterator();

    java.util.function.Function<String, Integer> function = Integer::valueOf;

    Iterator<Integer> result = Iterators.transform(sourceIterator, function);

    assertThat(result.hasNext()).isTrue();
    assertThat(result.next()).isEqualTo(1);

    // Remove should affect the underlying source iterator
    result.remove();

    // Verify the element was removed from the source list
    assertThat(input).containsExactly("2", "3").inOrder();

    // Verify the transformed iterator continues correctly
    assertThat(result.hasNext()).isTrue();
    assertThat(result.next()).isEqualTo(2);
    assertThat(result.next()).isEqualTo(3);
    assertThat(result.hasNext()).isFalse();
  }

  @Test
  public void testTransform_nullFunctionThrows() {
    List<String> input = Arrays.asList("1");
    Iterator<String> sourceIterator = input.iterator();

    assertThrows(NullPointerException.class, () -> {
      Iterators.transform(sourceIterator, (java.util.function.Function<String, Integer>) null);
    });
  }

  @Test
  public void testTransform_emptyIterator() {
    List<String> input = new ArrayList<>();
    Iterator<String> sourceIterator = input.iterator();

    java.util.function.Function<String, Integer> function = Integer::valueOf;

    Iterator<Integer> result = Iterators.transform(sourceIterator, function);

    assertThat(result.hasNext()).isFalse();
    assertThat(Lists.newArrayList(result)).isEmpty();
  }

  @Test
  public void testTransform_removeWithoutNextThrows() {
    List<String> input = new ArrayList<>(Arrays.asList("1"));
    Iterator<String> sourceIterator = input.iterator();

    java.util.function.Function<String, Integer> function = Integer::valueOf;

    Iterator<Integer> result = Iterators.transform(sourceIterator, function);

    assertThrows(IllegalStateException.class, () -> {
      result.remove();
    });
  }
}

