package com.google.common.collect;

import static com.google.common.truth.Truth.assertThat;
import static org.junit.Assert.assertThrows;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Iterator;
import java.util.List;
import java.util.function.Function;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;

@RunWith(JUnit4.class)
public class IteratorsTransformFunctionTest {

  @Test
  public void testTransform_basicTransformation() {
    Iterator<String> stringIterator = Arrays.asList("1", "2", "3").iterator();
    Function<String, Integer> parseInt = Integer::valueOf;

    Iterator<Integer> transformedIterator = Iterators.transform(stringIterator, parseInt);

    assertThat(transformedIterator.hasNext()).isTrue();
    assertThat(transformedIterator.next()).isEqualTo(1);
    assertThat(transformedIterator.next()).isEqualTo(2);
    assertThat(transformedIterator.next()).isEqualTo(3);
    assertThat(transformedIterator.hasNext()).isFalse();
  }

  @Test
  public void testTransform_removeSupported() {
    List<String> sourceList = new ArrayList<>(Arrays.asList("1", "2", "3"));
    Iterator<String> stringIterator = sourceList.iterator();
    Function<String, Integer> parseInt = Integer::valueOf;

    Iterator<Integer> transformedIterator = Iterators.transform(stringIterator, parseInt);

    assertThat(transformedIterator.next()).isEqualTo(1);
    transformedIterator.remove();

    // Source list should have the element removed
    assertThat(sourceList).containsExactly("2", "3").inOrder();
  }

  @Test
  public void testTransform_removeThrowsWithoutNext() {
    List<String> sourceList = new ArrayList<>(Arrays.asList("1", "2", "3"));
    Iterator<String> stringIterator = sourceList.iterator();
    Function<String, Integer> parseInt = Integer::valueOf;

    Iterator<Integer> transformedIterator = Iterators.transform(stringIterator, parseInt);

    assertThrows(IllegalStateException.class, () -> transformedIterator.remove());
  }

  @Test
  public void testTransform_functionNotNull() {
    Iterator<String> stringIterator = Arrays.asList("1", "2", "3").iterator();

    assertThrows(NullPointerException.class, () -> {
      Iterators.transform(stringIterator, null);
    });
  }

  @Test
  public void testTransform_emptyIterator() {
    Iterator<String> emptyIterator = Arrays.<String>asList().iterator();
    Function<String, Integer> parseInt = Integer::valueOf;

    Iterator<Integer> transformedIterator = Iterators.transform(emptyIterator, parseInt);

    assertThat(transformedIterator.hasNext()).isFalse();
  }

  @Test
  public void testTransform_withNullElements() {
    List<String> sourceList = new ArrayList<>(Arrays.asList("1", null, "3"));
    Iterator<String> stringIterator = sourceList.iterator();
    Function<String, Integer> parseInt = s -> s == null ? null : Integer.valueOf(s);

    Iterator<Integer> transformedIterator = Iterators.transform(stringIterator, parseInt);

    assertThat(transformedIterator.next()).isEqualTo(1);
    assertThat(transformedIterator.next()).isNull();
    assertThat(transformedIterator.next()).isEqualTo(3);
  }

  @Test
  public void testTransform_lazyEvaluation() {
    List<String> sourceList = new ArrayList<>(Arrays.asList("1", "2", "3"));
    Iterator<String> stringIterator = sourceList.iterator();
    Function<String, Integer> parseInt = Integer::valueOf;

    Iterator<Integer> transformedIterator = Iterators.transform(stringIterator, parseInt);

    // Transformation should be lazy - no elements processed yet
    assertThat(sourceList).hasSize(3);

    // Only process first element
    assertThat(transformedIterator.next()).isEqualTo(1);

    // Source list unchanged (lazy evaluation)
    assertThat(sourceList).hasSize(3);
  }

  @Test
  public void testTransform_methodReference() {
    Iterator<String> stringIterator = Arrays.asList("hello", "world").iterator();
    Function<String, Integer> lengthFunction = String::length;

    Iterator<Integer> transformedIterator = Iterators.transform(stringIterator, lengthFunction);

    assertThat(transformedIterator.next()).isEqualTo(5);
    assertThat(transformedIterator.next()).isEqualTo(5);
    assertThat(transformedIterator.hasNext()).isFalse();
  }

  @Test
  public void testTransform_removeAfterMultipleNext() {
    List<String> sourceList = new ArrayList<>(Arrays.asList("1", "2", "3"));
    Iterator<String> stringIterator = sourceList.iterator();
    Function<String, Integer> parseInt = Integer::valueOf;

    Iterator<Integer> transformedIterator = Iterators.transform(stringIterator, parseInt);

    assertThat(transformedIterator.next()).isEqualTo(1);
    assertThat(transformedIterator.next()).isEqualTo(2);
    transformedIterator.remove();

    // Should remove "2" from source
    assertThat(sourceList).containsExactly("1", "3").inOrder();
  }

  @Test
  public void testTransform_removeTwiceThrows() {
    List<String> sourceList = new ArrayList<>(Arrays.asList("1", "2", "3"));
    Iterator<String> stringIterator = sourceList.iterator();
    Function<String, Integer> parseInt = Integer::valueOf;

    Iterator<Integer> transformedIterator = Iterators.transform(stringIterator, parseInt);

    assertThat(transformedIterator.next()).isEqualTo(1);
    transformedIterator.remove();

    assertThrows(IllegalStateException.class, () -> transformedIterator.remove());
  }
}

