  @Test
  public void testExecuteSuccessOnFirstAttempt() throws Exception {
    RetryExecutor executor = RetryExecutor.builder()
        .maxRetries(3)
        .build();

    String result = executor.execute(() -> "success");
    assertThat(result).isEqualTo("success");
  }

  @Test
  public void testExecuteRetryOnRetryableException() throws Exception {
    AtomicInteger callCount = new AtomicInteger(0);
    RetryExecutor executor = RetryExecutor.builder()
        .maxRetries(3)
        .backoffMillis(1)
        .retryOn(IOException.class)
        .build();

    String result = executor.execute(() -> {
      int count = callCount.incrementAndGet();
      if (count < 3) {
        throw new IOException("Temporary failure");
      }
      return "success after " + count + " attempts";
    });

    assertThat(result).isEqualTo("success after 3 attempts");
    assertThat(callCount.get()).isEqualTo(3);
  }

