package com.google.common.collect;

import static com.google.common.truth.Truth.assertThat;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;

/**
 * Tests for EvictingQueue when maxSize is zero.
 * This verifies the fix for the Collection.add() contract violation where
 * add() was returning true even when maxSize == 0 and no element was added.
 */
@RunWith(JUnit4.class)
public class EvictingQueueMaxSizeZeroTest {

  @Test
  public void testAddWithMaxSizeZeroReturnsFalse() {
    EvictingQueue<String> queue = EvictingQueue.create(0);

    // When maxSize is 0, add() should return false (queue cannot be modified)
    boolean result = queue.add("hello");

    // Verify add() returns false
    assertThat(result).isFalse();
  }

  @Test
  public void testAddWithMaxSizeZeroQueueRemainsEmpty() {
    EvictingQueue<String> queue = EvictingQueue.create(0);

    // Attempt to add an element
    queue.add("hello");

    // Verify queue remains empty
    assertThat(queue.size()).isEqualTo(0);
  }

  @Test
  public void testAddWithMaxSizeZeroElementNotContained() {
    EvictingQueue<String> queue = EvictingQueue.create(0);

    // Attempt to add an element
    queue.add("hello");

    // Verify element was not added (Collection.add() contract: if add returns true, contains must return true)
    assertThat(queue.contains("hello")).isFalse();
  }

  @Test
  public void testOfferWithMaxSizeZeroReturnsFalse() {
    EvictingQueue<String> queue = EvictingQueue.create(0);

    // When maxSize is 0, offer() should also return false
    boolean result = queue.offer("hello");

    // Verify offer() returns false
    assertThat(result).isFalse();
  }

  @Test
  public void testOfferWithMaxSizeZeroQueueRemainsEmpty() {
    EvictingQueue<String> queue = EvictingQueue.create(0);

    // Attempt to offer an element
    queue.offer("hello");

    // Verify queue remains empty
    assertThat(queue.size()).isEqualTo(0);
  }

  @Test
  public void testAddWithMaxSizeZeroMultipleAttempts() {
    EvictingQueue<String> queue = EvictingQueue.create(0);

    // Attempt to add multiple elements
    assertThat(queue.add("first")).isFalse();
    assertThat(queue.add("second")).isFalse();
    assertThat(queue.add("third")).isFalse();

    // Verify queue remains empty after all attempts
    assertThat(queue.size()).isEqualTo(0);
  }

  @Test
  public void testAddWithMaxSizeGreaterThanZeroStillWorks() {
    EvictingQueue<String> queue = EvictingQueue.create(5);

    // When maxSize > 0, add() should return true and element should be added
    boolean result = queue.add("hello");

    // Verify add() returns true
    assertThat(result).isTrue();

    // Verify queue contains the element
    assertThat(queue.size()).isEqualTo(1);
    assertThat(queue.contains("hello")).isTrue();
  }

  @Test
  public void testAddWithMaxSizeZeroContractCompliance() {
    EvictingQueue<String> queue = EvictingQueue.create(0);

    // Collection.add() contract: if add(x) returns true, then contains(x) must return true
    // This test verifies the fix ensures this contract is not violated
    boolean addResult = queue.add("test");
    boolean containsResult = queue.contains("test");

    // If add returned true, contains must also return true (contract requirement)
    // Since maxSize == 0, add should return false, so this assertion should pass
    if (addResult) {
      assertThat(containsResult).isTrue();
    }

    // In this case, add should return false
    assertThat(addResult).isFalse();
    assertThat(containsResult).isFalse();
  }
}

