    public void testFlushBeforeClose() throws IOException {
        BaseEncoding encoding = BaseEncoding.base64();
        StringWriter writer = new StringWriter();
        OutputStream stream = encoding.encodingStream(writer);

        // Flush should work before close
        stream.write(0x41);
        stream.flush();
        stream.close();

        // Verify data was written
        String result = writer.toString();
        assertEquals("QQ==", result);
    }

    @Test
    public void testWriteAfterCloseWithMultipleOperations() throws IOException {
        BaseEncoding encoding = BaseEncoding.base64();
        StringWriter writer = new StringWriter();
        OutputStream stream = encoding.encodingStream(writer);

        stream.write(0x41);
        stream.close();

        // All operations should fail after close
