import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;

/**
 * Tests for the BaseEncoding encodingStream close() method behavior.
 * Validates that the stream properly handles closed state and idempotent close operations.
 */
@RunWith(JUnit4.class)
public class BaseEncodingCloseTest {

  private static final BaseEncoding BASE64 = BaseEncoding.base64();

  @Test
  public void testCloseIsIdempotent() throws IOException {
    // Given: An encoding stream
    StringWriter writer = new StringWriter();
    OutputStream stream = BASE64.encodingStream(writer);

    // When: Close is called twice
    stream.close();
    stream.close(); // Should not throw

    // Then: No exception is thrown (idempotent close)
  }

  @Test
  public void testWriteAfterCloseThrowsIOException() throws IOException {
    // Given: A closed encoding stream
    StringWriter writer = new StringWriter();
    OutputStream stream = BASE64.encodingStream(writer);
    stream.close();

    // When: Write is attempted on closed stream
    try {
      stream.write('A');
      fail("Expected IOException to be thrown");
    } catch (IOException e) {
      // Then: IOException is thrown with appropriate message
      assertThat(e.getMessage()).contains("closed");
    }
  }

  @Test
  public void testFlushAfterCloseThrowsIOException() throws IOException {
    // Given: A closed encoding stream
    StringWriter writer = new StringWriter();
    OutputStream stream = BASE64.encodingStream(writer);
    stream.close();

    // When: Flush is attempted on closed stream
    try {
      stream.flush();
      fail("Expected IOException to be thrown");
    } catch (IOException e) {
      // Then: IOException is thrown with appropriate message
      assertThat(e.getMessage()).contains("closed");
    }
  }

  @Test
  public void testNormalCloseWithPadding() throws IOException {
    // Given: An encoding stream with data that requires padding
    StringWriter writer = new StringWriter();
    OutputStream stream = BASE64.encodingStream(writer);

    // When: Write some data and close
    stream.write('A'); // Single byte, will need padding
    stream.close();

    // Then: Stream is properly closed with padding
    String encoded = writer.toString();
    assertThat(encoded).isNotEmpty();
    assertThat(encoded.endsWith("==")).isTrue(); // Base64 padding for 1 byte
  }

  @Test
  public void testNormalCloseWithoutPadding() throws IOException {
    // Given: An encoding stream with data that doesn't require padding
    StringWriter writer = new StringWriter();
    OutputStream stream = BASE64.encodingStream(writer);

    // When: Write 3 bytes (complete chunk) and close
    stream.write('A');
    stream.write('B');
    stream.write('C');
    stream.close();

    // Then: Stream is properly closed without extra padding
    String encoded = writer.toString();
    assertThat(encoded).isEqualTo("QUJD"); // Base64 for "ABC"
  }

  @Test
  public void testCloseWithoutWrite() throws IOException {
    // Given: An encoding stream with no data written
    StringWriter writer = new StringWriter();
    OutputStream stream = BASE64.encodingStream(writer);

    // When: Close immediately without writing
    stream.close();

    // Then: No exception, empty output
    String encoded = writer.toString();
    assertThat(encoded).isEmpty();
  }

  @Test
  public void testMultipleCloseAfterWrite() throws IOException {
    // Given: An encoding stream with data
    StringWriter writer = new StringWriter();
    OutputStream stream = BASE64.encodingStream(writer);
    stream.write('T');
    stream.write('e');
    stream.write('s');
    stream.write('t');

    // When: Close multiple times
    stream.close();
    stream.close();
    stream.close();

    // Then: All closes succeed without exception
    String encoded = writer.toString();
    assertThat(encoded).isNotEmpty();
  }

  @Test
  public void testWriteFlushCloseSequence() throws IOException {
    // Given: An encoding stream
    StringWriter writer = new StringWriter();
    OutputStream stream = BASE64.encodingStream(writer);

    // When: Normal write, flush, close sequence
    stream.write('H');
    stream.write('i');
    stream.flush();
    stream.close();

    // Then: Data is properly encoded
    String encoded = writer.toString();
    assertThat(encoded).isNotEmpty();
  }

  @Test
  public void testFlushBeforeClose() throws IOException {
    // Given: An encoding stream with data
    StringWriter writer = new StringWriter();
    OutputStream stream = BASE64.encodingStream(writer);
    stream.write('D');
    stream.write('a');
    stream.write('t');
    stream.write('a');

    // When: Flush before close
    stream.flush();
    stream.close();

    // Then: No exception, data encoded
    String encoded = writer.toString();
    assertThat(encoded).isNotEmpty();
  }

  @Test
  public void testClosePreventsFurtherOperations() throws IOException {
    // Given: A closed encoding stream
    StringWriter writer = new StringWriter();
    OutputStream stream = BASE64.encodingStream(writer);
    stream.write('X');
    stream.close();

    // When: Attempt various operations after close
    boolean writeFailed = false;
    boolean flushFailed = false;

    try {
      stream.write('Y');
    } catch (IOException e) {
      writeFailed = true;
    }

    try {
      stream.flush();
    } catch (IOException e) {
      flushFailed = true;
    }

    // Then: Both operations should fail
    assertThat(writeFailed).isTrue();
    assertThat(flushFailed).isTrue();
  }
}

