package com.google.common.primitives;

import static com.google.common.truth.Truth.assertThat;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Iterator;
import java.util.List;
import java.util.PrimitiveIterator;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;

/**
 * Tests for the primitive iterator support in Immutable*Array.asList()
 * 
 * This test verifies that the iterator() method in AsList wrapper classes
 * returns the appropriate PrimitiveIterator subtype, enabling boxing-free
 * iteration over immutable primitive arrays.
 */
@RunWith(JUnit4.class)
public class ImmutablePrimitiveArrayIteratorTest {

  @Test
  public void testImmutableDoubleArrayIteratorIsPrimitiveIterator() {
    ImmutableDoubleArray array = ImmutableDoubleArray.of(1.0, 2.0, 3.0);
    List<Double> list = array.asList();
    Iterator<Double> iterator = list.iterator();

    // Verify it's a PrimitiveIterator.OfDouble
    assertThat(iterator).isInstanceOf(PrimitiveIterator.OfDouble.class);
  }

  @Test
  public void testImmutableDoubleArrayIteratorPrimitiveNextDouble() {
    ImmutableDoubleArray array = ImmutableDoubleArray.of(1.0, 2.0, 3.0);
    List<Double> list = array.asList();
    PrimitiveIterator.OfDouble iterator = (PrimitiveIterator.OfDouble) list.iterator();

    // Test primitive iteration without boxing
    assertTrue(iterator.hasNext());
    assertEquals(1.0, iterator.nextDouble(), 0.0);
    assertTrue(iterator.hasNext());
    assertEquals(2.0, iterator.nextDouble(), 0.0);
    assertTrue(iterator.hasNext());
    assertEquals(3.0, iterator.nextDouble(), 0.0);
    assertFalse(iterator.hasNext());
  }

  @Test
  public void testImmutableIntArrayIteratorIsPrimitiveIterator() {
    ImmutableIntArray array = ImmutableIntArray.of(1, 2, 3);
    List<Integer> list = array.asList();
    Iterator<Integer> iterator = list.iterator();

    // Verify it's a PrimitiveIterator.OfInt
    assertThat(iterator).isInstanceOf(PrimitiveIterator.OfInt.class);
  }

  @Test
  public void testImmutableIntArrayIteratorPrimitiveNextInt() {
    ImmutableIntArray array = ImmutableIntArray.of(1, 2, 3);
    List<Integer> list = array.asList();
    PrimitiveIterator.OfInt iterator = (PrimitiveIterator.OfInt) list.iterator();

    // Test primitive iteration without boxing
    assertTrue(iterator.hasNext());
    assertEquals(1, iterator.nextInt());
    assertTrue(iterator.hasNext());
    assertEquals(2, iterator.nextInt());
    assertTrue(iterator.hasNext());
    assertEquals(3, iterator.nextInt());
    assertFalse(iterator.hasNext());
  }

  @Test
  public void testImmutableLongArrayIteratorIsPrimitiveIterator() {
    ImmutableLongArray array = ImmutableLongArray.of(1L, 2L, 3L);
    List<Long> list = array.asList();
    Iterator<Long> iterator = list.iterator();

    // Verify it's a PrimitiveIterator.OfLong
    assertThat(iterator).isInstanceOf(PrimitiveIterator.OfLong.class);
  }

  @Test
  public void testImmutableLongArrayIteratorPrimitiveNextLong() {
    ImmutableLongArray array = ImmutableLongArray.of(1L, 2L, 3L);
    List<Long> list = array.asList();
    PrimitiveIterator.OfLong iterator = (PrimitiveIterator.OfLong) list.iterator();

    // Test primitive iteration without boxing
    assertTrue(iterator.hasNext());
    assertEquals(1L, iterator.nextLong());
    assertTrue(iterator.hasNext());
    assertEquals(2L, iterator.nextLong());
    assertTrue(iterator.hasNext());
    assertEquals(3L, iterator.nextLong());
    assertFalse(iterator.hasNext());
  }

  @Test
  public void testEmptyDoubleArrayIterator() {
    ImmutableDoubleArray array = ImmutableDoubleArray.of();
    List<Double> list = array.asList();
    Iterator<Double> iterator = list.iterator();

    assertThat(iterator).isInstanceOf(PrimitiveIterator.OfDouble.class);
    assertFalse(iterator.hasNext());
  }

  @Test
  public void testEmptyIntArrayIterator() {
    ImmutableIntArray array = ImmutableIntArray.of();
    List<Integer> list = array.asList();
    Iterator<Integer> iterator = list.iterator();

    assertThat(iterator).isInstanceOf(PrimitiveIterator.OfInt.class);
    assertFalse(iterator.hasNext());
  }

  @Test
  public void testEmptyLongArrayIterator() {
    ImmutableLongArray array = ImmutableLongArray.of();
    List<Long> list = array.asList();
    Iterator<Long> iterator = list.iterator();

    assertThat(iterator).isInstanceOf(PrimitiveIterator.OfLong.class);
    assertFalse(iterator.hasNext());
  }

  @Test
  public void testSingleElementDoubleArrayIterator() {
    ImmutableDoubleArray array = ImmutableDoubleArray.of(5.5);
    List<Double> list = array.asList();
    PrimitiveIterator.OfDouble iterator = (PrimitiveIterator.OfDouble) list.iterator();

    assertTrue(iterator.hasNext());
    assertEquals(5.5, iterator.nextDouble(), 0.0);
    assertFalse(iterator.hasNext());
  }

  @Test
  public void testSingleElementIntArrayIterator() {
    ImmutableIntArray array = ImmutableIntArray.of(42);
    List<Integer> list = array.asList();
    PrimitiveIterator.OfInt iterator = (PrimitiveIterator.OfInt) list.iterator();

    assertTrue(iterator.hasNext());
    assertEquals(42, iterator.nextInt());
    assertFalse(iterator.hasNext());
  }

  @Test
  public void testSingleElementLongArrayIterator() {
    ImmutableLongArray array = ImmutableLongArray.of(999L);
    List<Long> list = array.asList();
    PrimitiveIterator.OfLong iterator = (PrimitiveIterator.OfLong) list.iterator();

    assertTrue(iterator.hasNext());
    assertEquals(999L, iterator.nextLong());
    assertFalse(iterator.hasNext());
  }

  @Test
  public void testDoubleArrayIteratorWithNegativeAndZero() {
    ImmutableDoubleArray array = ImmutableDoubleArray.of(-1.5, 0.0, 1.5);
    List<Double> list = array.asList();
    PrimitiveIterator.OfDouble iterator = (PrimitiveIterator.OfDouble) list.iterator();

    assertEquals(-1.5, iterator.nextDouble(), 0.0);
    assertEquals(0.0, iterator.nextDouble(), 0.0);
    assertEquals(1.5, iterator.nextDouble(), 0.0);
    assertFalse(iterator.hasNext());
  }

  @Test
  public void testIntArrayIteratorWithNegativeAndZero() {
    ImmutableIntArray array = ImmutableIntArray.of(-10, 0, 10);
    List<Integer> list = array.asList();
    PrimitiveIterator.OfInt iterator = (PrimitiveIterator.OfInt) list.iterator();

    assertEquals(-10, iterator.nextInt());
    assertEquals(0, iterator.nextInt());
    assertEquals(10, iterator.nextInt());
    assertFalse(iterator.hasNext());
  }

  @Test
  public void testLongArrayIteratorWithNegativeAndZero() {
    ImmutableLongArray array = ImmutableLongArray.of(-100L, 0L, 100L);
    List<Long> list = array.asList();
    PrimitiveIterator.OfLong iterator = (PrimitiveIterator.OfLong) list.iterator();

    assertEquals(-100L, iterator.nextLong());
    assertEquals(0L, iterator.nextLong());
    assertEquals(100L, iterator.nextLong());
    assertFalse(iterator.hasNext());
  }

  @Test
  public void testDoubleArrayIteratorGenericNextStillWorks() {
    ImmutableDoubleArray array = ImmutableDoubleArray.of(1.0, 2.0);
    List<Double> list = array.asList();
    Iterator<Double> iterator = list.iterator();

    // Test that the generic next() method still works (returns boxed Double)
    assertThat(iterator).isInstanceOf(PrimitiveIterator.OfDouble.class);
    assertEquals(Double.valueOf(1.0), iterator.next());
    assertEquals(Double.valueOf(2.0), iterator.next());
    assertFalse(iterator.hasNext());
  }

  @Test
  public void testIntArrayIteratorGenericNextStillWorks() {
    ImmutableIntArray array = ImmutableIntArray.of(1, 2);
    List<Integer> list = array.asList();
    Iterator<Integer> iterator = list.iterator();

    // Test that the generic next() method still works (returns boxed Integer)
    assertThat(iterator).isInstanceOf(PrimitiveIterator.OfInt.class);
    assertEquals(Integer.valueOf(1), iterator.next());
    assertEquals(Integer.valueOf(2), iterator.next());
    assertFalse(iterator.hasNext());
  }

  @Test
  public void testLongArrayIteratorGenericNextStillWorks() {
    ImmutableLongArray array = ImmutableLongArray.of(1L, 2L);
    List<Long> list = array.asList();
    Iterator<Long> iterator = list.iterator();

    // Test that the generic next() method still works (returns boxed Long)
    assertThat(iterator).isInstanceOf(PrimitiveIterator.OfLong.class);
    assertEquals(Long.valueOf(1L), iterator.next());
    assertEquals(Long.valueOf(2L), iterator.next());
    assertFalse(iterator.hasNext());
  }

  @Test
  public void testDoubleArrayIteratorForEachLoop() {
    ImmutableDoubleArray array = ImmutableDoubleArray.of(1.0, 2.0, 3.0);
    List<Double> list = array.asList();

    double sum = 0.0;
    for (Double d : list) {
      sum += d;
    }
    assertEquals(6.0, sum, 0.0);
  }

  @Test
  public void testIntArrayIteratorForEachLoop() {
    ImmutableIntArray array = ImmutableIntArray.of(1, 2, 3);
    List<Integer> list = array.asList();

    int sum = 0;
    for (Integer i : list) {
      sum += i;
    }
    assertEquals(6, sum);
  }

  @Test
  public void testLongArrayIteratorForEachLoop() {
    ImmutableLongArray array = ImmutableLongArray.of(1L, 2L, 3L);
    List<Long> list = array.asList();

    long sum = 0L;
    for (Long l : list) {
      sum += l;
    }
    assertEquals(6L, sum);
  }

  @Test
  public void testDoubleArrayIteratorCanBeCheckedForPrimitiveType() {
    // This test demonstrates the use case from the requirement:
    // Legacy API that must accept List<Double> can check for PrimitiveIterator
    ImmutableDoubleArray array = ImmutableDoubleArray.of(1.0, 2.0, 3.0);
    List<Double> list = array.asList();

    Iterator<Double> iterator = list.iterator();
    if (iterator instanceof PrimitiveIterator.OfDouble) {
      PrimitiveIterator.OfDouble pi = (PrimitiveIterator.OfDouble) iterator;
      double sum = 0.0;
      while (pi.hasNext()) {
        sum += pi.nextDouble(); // No boxing!
      }
      assertEquals(6.0, sum, 0.0);
    } else {
      // This branch should not be reached with the fix
      throw new AssertionError("Iterator should be PrimitiveIterator.OfDouble");
    }
  }

  @Test
  public void testIntArrayIteratorCanBeCheckedForPrimitiveType() {
    ImmutableIntArray array = ImmutableIntArray.of(1, 2, 3);
    List<Integer> list = array.asList();

    Iterator<Integer> iterator = list.iterator();
    if (iterator instanceof PrimitiveIterator.OfInt) {
      PrimitiveIterator.OfInt pi = (PrimitiveIterator.OfInt) iterator;
      int sum = 0;
      while (pi.hasNext()) {
        sum += pi.nextInt(); // No boxing!
      }
      assertEquals(6, sum);
    } else {
      throw new AssertionError("Iterator should be PrimitiveIterator.OfInt");
    }
  }

  @Test
  public void testLongArrayIteratorCanBeCheckedForPrimitiveType() {
    ImmutableLongArray array = ImmutableLongArray.of(1L, 2L, 3L);
    List<Long> list = array.asList();

    Iterator<Long> iterator = list.iterator();
    if (iterator instanceof PrimitiveIterator.OfLong) {
      PrimitiveIterator.OfLong pi = (PrimitiveIterator.OfLong) iterator;
      long sum = 0L;
      while (pi.hasNext()) {
        sum += pi.nextLong(); // No boxing!
      }
      assertEquals(6L, sum);
    } else {
      throw new AssertionError("Iterator should be PrimitiveIterator.OfLong");
    }
  }
}

