  @Test
  public void testLegacyApiCompatibilityWithPrimitiveIterator() {
    // Simulates the use case from the requirement where legacy API accepts List<Double>
    // but can detect and use PrimitiveIterator for performance
    List<Double> scores = ImmutableDoubleArray.of(1.0, 2.0, 3.0).asList();
    Iterator<Double> iterator = scores.iterator();

    // Legacy code can check for PrimitiveIterator to avoid boxing
    if (iterator instanceof PrimitiveIterator.OfDouble) {
